def _norm(s: str) -> str:
    return re.sub(r"[^a-z]", "", s.lower())


def lookup(label: str) -> dict:
    n = _norm(label)
    for keys, cause, symptoms, actions in _KB:
        if all(k in n for k in keys):
            return {"cause": cause, "symptoms": symptoms, "actions": actions}
    return {"cause": "—", "symptoms": "", "actions": []}
